def reviewer_for_block(block_file: str | Path) -> str:
    label_re = re.compile(
        r"^[\s-]*(?:\*\*Reviewer\(s\)\*\*|\*\*Reviewers?\*\*|Reviewer\(s\)|Reviewers?)\s*:"
    )
    try:
        lines = Path(block_file).read_text(encoding="utf-8", errors="replace").splitlines()
