WAIT_DEFAULT_TIMEOUT = 1860
WAIT_DEFAULT_POLL_INTERVAL = "5"
SUSPEND_REFUND_SECONDS = 60
GENERATORS_TSV_COLUMNS = 2
_FAILED_AGENT_TAIL_LINES = 30
